WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($companies$[{"company_id":"rbc-capital-markets","name":"RBC Capital Markets","company_type":"Investment Bank","headquarters_country":null,"status":"active"},{"company_id":"hoopp","name":"HOOPP","company_type":"Private Equity","headquarters_country":null,"status":"active"}]$companies$::jsonb)
  AS company(company_id text, name text, company_type text, headquarters_country text, status text)
)
INSERT INTO public.companies (company_id, name, company_type, headquarters_country, status, updated_at)
SELECT company_id, name, company_type, headquarters_country, status, now()
FROM incoming
ON CONFLICT DO NOTHING;

WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($jobs$[{"external_job_id":"R-0000189234","company_id":"rbc-capital-markets","company_name":"RBC Capital Markets","title":"Analyst, Global Investment Banking (Diversified - Consumer & Industrial Products)","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Investment Banking","specialization":null,"seniority":"Analyst","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-10-01","application_deadline":"2026-10-18","salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"https://rbc.wd3.myworkdayjobs.com/RBCGLOBAL1/job/TORONTO-Ontario-Canada/Analyst--Global-Investment-Banking--Diversified---Consumer---Industrial-Products-_R-0000189234-1/apply","source_url":"https://jobs.rbc.com/ca/en/job/RBCAA0088R0000189234EXTERNALENCA/Analyst-Global-Investment-Banking-Diversified-Consumer-and-Industrial-Products","source_name":"RBC Capital Markets public careers site","status":"active","summary":"Analyst Investment Banking opportunity with RBC Capital Markets in Toronto, ON.","description_text":"Job Description \n RBC Capital Markets is a part of the Royal Bank of Canada, one of the largest providers of financial services in the world. RBC ranks among the top five banks in North America by market capitalization and has one of the highest credit ratings of any financial institution globally.\n  \n Our Global Investment Banking division provides underwriting of equity and debt capital as well as strategic M&A advisory services for leading corporations, institutions and governments throughout North America and around the world. RBC Capital Markets is Canada’s leading investment bank. We have built our successful investment banking business by focusing on our clients and the industry sectors in which they operate. With teams located in North America, Europe, Australia and Asia, we offer clients across the public and private sectors insightful financial advice, bring a competitive advantage on funding solutions, and assist in navigating complex investment decisions.\n  \n What is the opportunity? \n  \n \n RBC Capital Markets Global Investment Banking division is seeking an Analyst to join the Diversified (“Consumer & Industrial Products”) team based in Toronto. The Consumer & Industrial Products team works across a variety of industries, including Consumer & Retail, Industrial, Communications, Media & Entertainment, Healthcare, Business Services and other. We support our clients through a variety of transactions including M&A, strategic alternative mandates, capital structure advisory and equity and debt financings. The Analyst role involves working collaboratively with product and coverage partners across RBC’s global platform to deliver the best advice possible to our clients.\n  \n The Analyst position is a unique opportunity to develop a broad financial skillset and gain exposure to global capital markets. The role is intended for individuals who wish to build a long-term career in Investment Banking with a market leading franchise and global platform.\n  \n What will you do? \n  \n - - Evaluating and analyzing the financial needs of corporate clients, including developing and preserving complex financial models\n- Supporting transaction structuring and execution efforts, with increasing levels of responsibility and accountability over time\n- Financial and written analysis of companies and industries\n- Contributing to the delivery of client meetings and presentations\n- Conducting research to analyze market trends\n- Researching and analyzing future opportunities\n- Contribute to the execution of equity and debt financings, mergers and acquisitions, and financial advisory assignments\n \n   \n What do you need to succeed? \n  \n - - 1-2 years of investment banking, private equity, equity research, corporate development or advisory experience (corporate finance, transaction services, valuations, etc.)\n- Undergraduate degree program in Finance, Accounting, Engineering or a quantitative field from a leading university\n- Strong quantitative skills focused on financial analysis, accounting and financial theory\n- Strong verbal and written communication skills\n- A high level of attention to detail\n- Ability to manage multiple competing priorities and thrive in a fast-paced and challenging environment\n- Value and possess strong competency in the following behaviors: Collaboration, Relationship Building, Communication, Integrity and Operating with Diverse and Inclusive Mindset\n- The ability to perform effectively in a team environment and excel under pressure amid demanding deadlines\n- Well-rounded set of interests and extra-curricular activities beyond academics\n- Desire to develop a leadership skillset and make meaningful contributions in a fast-paced, team environment\n- CFA and / or CPA ,or other relevant professional designations, are considered an asset, but not a requirement\n \n  \n What’s in it for you? \n  \n We thrive on the challenge to be our best, think progressively, continue our growth, and deliver trusted advice to help our clients thrive and communities prosper. We care about each other, reaching our individual / collective potential, making a difference to our communities, and achieving success that is mutual.\n  \n - - A comprehensive Total Rewards Program including bonuses and flexible benefits, competitive compensation\n- Leaders who support your development through coaching and managing opportunities \n- Work in a dynamic, collaborative, progressive, and high-performing team\n- Opportunities to do challenging work\n- Flexible work/life balance options\n- A strong foundation in fundamental investment banking skills such as financial modeling and analysis, transaction execution and negotiation, and in-depth industry and product knowledge\n- An ability to make a difference through impactful transactions which help shape an industry\n- Analytical expertise and skillset through real world transaction experience\n- Exposure and insight into the global capital markets\n- Direct access with senior levels of Canada’s largest and fastest growing companies\n- The ability to build a long-term career in Investment Banking\n \n \n\n Required Documents: Cover letter, Resume and Academic Transcripts (unofficial are acceptable) in one PDF document. Please ensure you submit these three documents in one PDF document under the “resume” section. Do not submit them separately.\n\n We thank all interested candidates; however, only those selected for an interview will be contacted.\n\n RBC is presently inviting candidates to apply for this existing vacancy. Applying to this posting allows you to express your interest in this current career opportunity at RBC. Qualified applicants may be contacted to review their resume in more detail.\n \n\n \n Job Skills \nAdaptability, Critical Thinking, Customer Service, Detail-Oriented, Financial Engineering, Financial Statement Analysis, Investments Analysis, Personal Development, Personal Initiative, Teamwork \n Additional Job Details \n Address: \nROYAL BANK PLAZA, 200 BAY ST:TORONTO City: \nToronto Country: \nCanada Work hours/week: \n37.5 Employment Type: \nFull time Platform: \nCAPITAL MARKETS Job Type: \nRegular Pay Type: \nSalaried Posted Date: \n2026-10-01 Application Deadline: \n2026-10-18 Note: Applications will be accepted until 11:59 PM on the day prior to the application deadline date above \n \n Compensation for this position (including salary and discretionary/variable payments) will be determined by factors, including but not limited to candidate's experience, skills, registration status, performance, individual goals, market conditions, and business needs.\n \n Pay Range \n The expected pay range for this position is:\n$75,000.00 - $115,000.00 \n The pay range provided is for the primary work location referenced in the Additional Job Details section of this job posting. Pay ranges may differ based on location. If the posting lists multiple job locations, a recruiter can confirm availability of the role and the relevant pay rage for the additional locations listed. RBC supports pay transparency and we strive to ensure all pay ranges are competitive, fair, and equitable. \n \n You have the potential to earn RBC's discretionary variable compensation program which gives you an opportunity to increase your total compensation, provided that business meets its performance targets and you meet your individual goals.\n \n Our Employment Opportunities \n \n At RBC, we are guided by living shared values of Client First, Integrity, Collaboration, Respect and Excellence and winning together as One RBC. We believe an inclusive workplace that has diverse perspectives is core to our continued growth as one of the largest and most successful banks in the world. Maintaining a workplace where our employees feel supported to perform at their best, effectively collaborate, drive innovation, and grow professionally helps to bring our Purpose to life and create value for our clients and communities. RBC strives to deliver this through policies and programs intended to foster a workplace based on respect, belonging and opportunity for all.\n \n Join our Talent Community \n \n Stay in-the-know about great career opportunities at RBC. Sign up and get customized info on our latest jobs, career tips and Recruitment events that matter to you. \n \n Expand your limits and create a new future together at RBC. Find out how we use our passion and drive to enhance the well-being of our clients and communities at jobs.rbc.com .\n \n RBC is presently inviting candidates to apply for this existing vacancy. Applying to this posting allows you to express your interest in this current career opportunity at RBC. Qualified applicants may be contacted to review their resume in more detail.","description_status":"verified","description_verified_at":"2026-10-02T12:07:17.850Z","source_record_id":"rbc:R-0000189234","data_quality_notes":"Role-specific Investment Banking evidence found in title.","last_verified_at":"2026-10-02T12:07:17.850Z","updated_at":"2026-10-02T12:07:17.850Z"},{"external_job_id":"JR102589","company_id":"hoopp","company_name":"HOOPP","title":"Associate, Private Equity","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Private Equity","specialization":"Private Equity","seniority":"Associate","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-10-01","application_deadline":"2026-10-30","salary_min":98000,"salary_max":148000,"salary_currency":"CAD","salary_period":"year","application_url":"https://hoopp.wd10.myworkdayjobs.com/HOOPP/job/Toronto-Ontario-Canada/Associate--Private-Equity_JR102589","source_url":"https://hoopp.wd10.myworkdayjobs.com/HOOPP/job/Toronto-Ontario-Canada/Associate--Private-Equity_JR102589","source_name":"HOOPP public careers site","status":"active","summary":"Associate Private Equity opportunity with HOOPP in Toronto, ON focused on Private Equity.","description_text":"Why you’ll love working here: high-performance, people-focused culture our commitment that equity, diversity, and inclusion are fundamental to our work environment and business success, which helps employees feel valued and empowered to be their authentic selves learning and development initiatives, including workshops, Speaker Series events and access to LinkedIn Learning, that support employees’ career growth membership in HOOPP’s world class defined benefit pension plan, which can serve as an important part of your retirement security competitive, 100% company-paid extended health and dental benefits for permanent employees, including coverage supporting our team's diversity and mental health (e.g., gender affirmation, fertility and drug treatment, psychological support benefits of $2,500 per year, parental leave top-up, and a health spending account). optional post-retirement health and dental benefits subsidized at 50% yoga classes, meditation workshops, nutritional consultations, and wellness seminars the opportunity to make a difference and help take care of those who care for us, by providing a financially secure retirement for Ontario healthcare workers About HOOPP and HCP The Healthcare of Ontario Pension Plan (HOOPP) is one of the top-performing and fastest-growing pension funds in the world, with $132 billion in net assets under management globally. HOOPP invests in all major asset classes, including fixed income, public equity, credit, private equity, real estate, and infrastructure, and is headquartered in Toronto, Canada. At HOOPP, we are committed to providing secure retirement income to over 475,000 Ontario healthcare workers, while maintaining a high-performance culture of integrity, collaboration, and continuous learning. HOOPP Capital Partners (“HCP”) is the private equity arm of the Healthcare of Ontario Pension Plan (HOOPP), managing over $20 billion in assets. Our team executes investments globally across direct, co-investment, and fund strategies, with the ability to invest across the capital structure. Job Summary As an Associate on the HCP team, you will gain hands-on exposure to the full investment lifecycle, including sourcing, evaluating, executing, and monitoring private equity investments. This is a foundational role designed for intellectually curious, motivated individuals eager to contribute to a lean, collaborative team and grow within private markets investing. You will work closely with senior investment professionals, playing a meaningful role in both investment execution and portfolio management. The role offers strong development opportunities with increasing responsibility based on performance. What you will do: Investment Execution Support due diligence on potential direct investment, co-investment and fund opportunities Build and maintain dynamic and user-friendly financial models for valuation and return analysis Prepare and contribute to investment memos and committee materials Conduct industry, company, and market research to inform investment theses Assist in evaluating deal structuring options, terms, and implications Portfolio Management Monitor financial and operational performance of portfolio companies and fund investments Assist with periodic valuations, performance attribution, and reporting on existing investments Investigate and model financing alternatives or follow-on investment opportunities Strategic and Internal Initiatives Contribute to research and analysis on investment themes, sectors, and structures Support internal strategic initiatives including process improvements and knowledge sharing Engage with internal stakeholders across legal, tax, and operations to support deal execution What you bring: 2-4 years of experience in investment banking or private equity University degree in Finance, Commerce, Economics, Engineering, or a quantitative field with strong academic performance Demonstrated strong skills in financial modeling, business analysis, and due diligence Expert proficiency in Microsoft Excel, PowerPoint, and Word; knowledge of Capital IQ, Bloomberg, or other data tools is an asset Strong communication and writing skills with the ability to synthesize complex ideas clearly Curious mindset, strong attention to detail, and a proactive attitude High integrity, professionalism, and team orientation The expected annual base salary range for this role is: $98,000 - $148,000 CAD The actual base salary offered to the successful candidate may vary based on multiple factors including, but not limited to, individual's expertise and level of experience applicable to the role they are being offered. This role is eligible to participate in discretionary incentive plan(s), subject to the terms and conditions of the applicable incentive plan text. This job is for an existing vacancy. HOOPP may use artificial intelligence tools to assist in screening, assessing and selecting applicants for this position. These tools support our recruitment process but do not replace human judgment and decision-making.","description_status":"verified","description_verified_at":"2026-10-02T12:07:17.850Z","source_record_id":"hoopp:JR102589","data_quality_notes":"Description establishes direct investment research, underwriting, execution, selection, allocation or portfolio-management responsibility.","last_verified_at":"2026-10-02T12:07:17.850Z","updated_at":"2026-10-02T12:07:17.850Z"}]$jobs$::jsonb)
  AS job(
    external_job_id text, company_id text, company_name text, title text, location_display text, city text, province text,
    country text, workplace_type text, category text, specialization text, seniority text, employment_type text,
    program_type text, term_start text, term_end text, term_length_months integer, date_posted text,
    application_deadline text, salary_min numeric, salary_max numeric, salary_currency text, salary_period text,
    application_url text, source_url text, source_name text, status text, summary text, description_text text,
    description_status text, description_verified_at text, source_record_id text, data_quality_notes text,
    last_verified_at text, updated_at text
  )
)
INSERT INTO public.jobs (external_job_id, company_id, company_name, title, location_display, city, province, country, workplace_type, category, specialization, seniority, employment_type, program_type, term_start, term_end, term_length_months, date_posted, application_deadline, salary_min, salary_max, salary_currency, salary_period, application_url, source_url, source_name, status, summary, description_text, description_status, description_verified_at, source_record_id, data_quality_notes, last_verified_at, updated_at)
SELECT
  job.external_job_id,
  COALESCE((SELECT company_id FROM public.companies WHERE name = job.company_name), job.company_id),
  job.company_name, job.title, job.location_display, job.city, job.province, job.country, job.workplace_type,
  job.category, job.specialization, job.seniority, job.employment_type, job.program_type,
  NULLIF(job.term_start, '')::date, NULLIF(job.term_end, '')::date, job.term_length_months,
  NULLIF(job.date_posted, '')::date, NULLIF(job.application_deadline, '')::date,
  job.salary_min, job.salary_max, job.salary_currency, job.salary_period,
  job.application_url, job.source_url, job.source_name, job.status, job.summary, job.description_text,
  job.description_status, NULLIF(job.description_verified_at, '')::timestamptz, job.source_record_id,
  job.data_quality_notes, NULLIF(job.last_verified_at, '')::timestamptz, now()
FROM incoming AS job
ON CONFLICT (source_record_id) DO UPDATE SET
  company_name = EXCLUDED.company_name,
  title = EXCLUDED.title,
  location_display = EXCLUDED.location_display,
  city = EXCLUDED.city,
  province = EXCLUDED.province,
  country = EXCLUDED.country,
  workplace_type = EXCLUDED.workplace_type,
  category = EXCLUDED.category,
  specialization = EXCLUDED.specialization,
  seniority = EXCLUDED.seniority,
  employment_type = EXCLUDED.employment_type,
  program_type = EXCLUDED.program_type,
  term_start = EXCLUDED.term_start,
  term_end = EXCLUDED.term_end,
  term_length_months = EXCLUDED.term_length_months,
  date_posted = EXCLUDED.date_posted,
  application_deadline = EXCLUDED.application_deadline,
  salary_min = EXCLUDED.salary_min,
  salary_max = EXCLUDED.salary_max,
  salary_currency = EXCLUDED.salary_currency,
  salary_period = EXCLUDED.salary_period,
  application_url = EXCLUDED.application_url,
  source_url = EXCLUDED.source_url,
  source_name = EXCLUDED.source_name,
  status = EXCLUDED.status,
  summary = EXCLUDED.summary,
  description_text = EXCLUDED.description_text,
  description_status = EXCLUDED.description_status,
  description_verified_at = EXCLUDED.description_verified_at,
  data_quality_notes = EXCLUDED.data_quality_notes,
  last_verified_at = EXCLUDED.last_verified_at,
  updated_at = now();

-- Close roles no longer returned by completed authoritative employer scans.
UPDATE public.jobs
SET
  status = 'closed',
  featured = false,
  data_quality_notes = concat_ws(' ', nullif(data_quality_notes, ''), 'Closed October 2, 2026 after the role was absent from a completed authoritative structured-source scan.'),
  last_verified_at = now(),
  updated_at = now()
WHERE source_record_id = ANY (ARRAY[
  'hoopp:JR102445',
  'bci:JR101582',
  'bci:JR101581'
]);
